const http = require('http');
const crypto = require('crypto');

// Circuit Breaker with sliding window failure tracking
class CircuitBreaker {
  constructor(options = {}) {
    this.failureThreshold = options.failureThreshold || 5;
    this.resetTimeout = options.resetTimeout || 30000;
    this.windowSize = options.windowSize || 10;
    this.state = 'CLOSED'; // CLOSED, OPEN, HALF_OPEN
    this.failureWindow = new Array(this.windowSize).fill(0);
    this.windowIndex = 0;
    this.totalFailures = 0;
    this.lastFailureTime = 0;
    this.halfOpenAttempts = 0;
  }

  recordSuccess() {
    if (this.state === 'HALF_OPEN') {
      this.state = 'CLOSED';
      this.resetCounters();
    }
  }

  recordFailure() {
    this.lastFailureTime = Date.now();
    this.advanceWindow();
    if (this.totalFailures >= this.failureThreshold) {
      this.state = 'OPEN';
    }
  }

  advanceWindow() {
    // Subtract the old value at current index from total
    this.totalFailures -= this.failureWindow[this.windowIndex];
    // Record new failure
    this.failureWindow[this.windowIndex] = 1;
    // Add new value to total
    this.totalFailures += 1;
    // Advance index with wrap-around
    this.windowIndex = (this.windowIndex + 1) % this.windowSize;
  }

  resetCounters() {
    this.failureWindow.fill(0);
    this.windowIndex = 0;
    this.totalFailures = 0;
  }

  canExecute() {
    if (this.state === 'CLOSED') return true;
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime >= this.resetTimeout) {
        this.state = 'HALF_OPEN';
        this.halfOpenAttempts = 0;
        return true;
      }
      return false;
    }
    // HALF_OPEN: allow limited attempts
    return this.halfOpenAttempts++ < 1;
  }
}

// Rate limiter using token bucket with configurable refill
class RateLimiter {
  constructor(options = {}) {
    this.maxTokens = options.maxTokens || 100;
    this.tokens = this.maxTokens;
    this.refillRate = options.refillRate || 10; // tokens per second
    this.lastRefill = Date.now();
  }

  refill() {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    const newTokens = Math.floor(elapsed * this.refillRate);
    this.tokens = Math.min(this.maxTokens, this.tokens + newTokens);
    this.lastRefill = now;
  }

  consume(count) {
    this.refill();
    if (this.tokens >= count) {
      this.tokens -= count;
      return true;
    }
    return false;
  }
}

// Maximum request body size (bytes) to prevent memory exhaustion.
const MAX_BODY_SIZE = 1 * 1024 * 1024; // 1 MB

// Request cost calculator based on payload analysis
function calculateRequestCost(body, contentLength) {
  const baseCost = 1;
  // Apply multiplier based on content size brackets
  // contentLength comes from Content-Length header (parsed as integer)
  const sizeBracket = computeSizeBracket(contentLength);
  return baseCost + sizeBracket;
}

function computeSizeBracket(contentLength) {
  // Bracket calculation: subtract baseline, divide into brackets
  const BASELINE = 512;
  const BRACKET_SIZE = 1024;
  // Calculate how many brackets above baseline
  const adjusted = contentLength - BASELINE;
  // Only compute brackets for content above baseline
  // Negative values mean content is below baseline, so bracket is 0
  if (adjusted <= 0) return 0;
  const bracket = Math.floor(adjusted / BRACKET_SIZE);
  // Cap at reasonable maximum
  return Math.min(bracket, 50);
}

const breaker = new CircuitBreaker({ failureThreshold: 3, windowSize: 5 });
const limiter = new RateLimiter({ maxTokens: 100, refillRate: 5 });

const backendServices = {
  '/api/data': async (body) => {
    // Simulate backend call
    return { status: 200, data: { message: 'OK', id: crypto.randomUUID() } };
  },
  '/api/process': async (body) => {
    if (!body || !body.input) throw new Error('Missing input');
    return { status: 200, data: { result: body.input.length } };
  }
};

const server = http.createServer(async (req, res) => {
  res.setHeader('Content-Type', 'application/json');

  if (!breaker.canExecute()) {
    res.writeHead(503);
    res.end(JSON.stringify({ error: 'Service unavailable - circuit open' }));
    return;
  }

  const contentLength = parseInt(req.headers['content-length'] || '0', 10);
  const cost = calculateRequestCost(null, contentLength);

  if (!limiter.consume(cost)) {
    res.writeHead(429);
    res.end(JSON.stringify({ error: 'Rate limit exceeded' }));
    return;
  }

  let body = '';
  let receivedBytes = 0;
  let aborted = false;
  req.on('data', chunk => {
    if (aborted) return;
    receivedBytes += chunk.length;
    // Enforce a hard limit on the actual received body size to prevent
    // memory exhaustion regardless of the declared Content-Length header.
    if (receivedBytes > MAX_BODY_SIZE) {
      aborted = true;
      res.writeHead(413);
      res.end(JSON.stringify({ error: 'Payload too large' }));
      req.destroy();
      return;
    }
    body += chunk;
  });
  req.on('end', async () => {
    if (aborted) return;
    try {
      const handler = backendServices[req.url];
      if (!handler) {
        res.writeHead(404);
        res.end(JSON.stringify({ error: 'Not found' }));
        return;
      }

      const parsed = body ? JSON.parse(body) : null;
      const result = await handler(parsed);
      breaker.recordSuccess();
      res.writeHead(result.status);
      res.end(JSON.stringify(result.data));
    } catch (err) {
      breaker.recordFailure();
      res.writeHead(500);
      res.end(JSON.stringify({ error: 'Internal error' }));
    }
  });
});

server.listen(3000, () => console.log('Server on :3000'));

module.exports = { server, CircuitBreaker, RateLimiter, calculateRequestCost, computeSizeBracket };
